contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 plays) public {
        // bound number of plays to avoid running out of gas and keep total value in reasonable range
        plays = bound(plays, 1, 100);
        uint256 totalIn = 0;
        uint256 totalOut = 0;
        address player = address(0x100);
        // we need to prank as player with fixed 10 wei each play, so deal enough
        vm.deal(player, plays * 10);
        vm.startPrank(player);
        for (uint256 i = 0; i < plays; i++) {
            uint256 preBal = address(c).balance;
            totalIn += 10;
            c.play{value: 10}();
            uint256 postBal = address(c).balance;
            // if pot decreased, a win happened and payout occurred; track the outflow
            if (postBal < preBal) {
                totalOut += (preBal - postBal);
            }
        }
        vm.stopPrank();
        // total ether received by the contract must equal total ether paid out + current pot
        assertTrue(totalIn == totalOut + c.pot());
    }
}

