pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint8 numCalls) public {
        vm.assume(numCalls >= 1 && numCalls <= 10);
        uint256 totalSent = 0;
        uint256 bankBalance = 0;
        uint256 winnersPaid = 0;
        for (uint i = 0; i < numCalls; i++) {
            address player = address(uint160(uint(keccak256(abi.encodePacked(i, "player")))));
            vm.deal(player, 10);
            vm.prank(player);
            c.play{value: 10}();
            totalSent += 10;
        }
        // The bank gets 1 fee for each win (when random==0).
        // We record bank balance and each player's balance change for wins.
        // Instead of replaying random, we check the invariant:
        // pot = totalSent - (bankBalance + winnersPaid)
        // Since we can't know random outcome directly, we compute bankBalance by observing bank's balance.
        // But bank is an address that receives 1 wei per win. We can compute total fees = address(bank).balance.
        // Then pot should satisfy: pot = totalSent - totalFees - (totalWinnersPaid).
        // Since totalWinnersPaid = totalSent - totalFees - pot at any point if the invariant holds,
        // we check: pot <= totalSent - address(bank).balance.
        // This is always true for the reference because pot is reset after each win, but the mutant may accumulate pot beyond this.
        assertTrue(c.pot() <= totalSent - address(c.bank()).balance);
    }
}

